'use strict';
const $=s=>document.querySelector(s);
const e=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const state={page:localStorage.getItem('cay.page')||'overview',project:localStorage.getItem('cay.project')||'mafia-01',filter:'all',data:null,chat:null,chatSignature:'',polling:false};
const pages=[['overview','Übersicht'],['chat','Regiechat'],['projects','Projekte'],['production','Produktion'],['media','Filme & Vorschauen'],['queue','Warteschlange'],['channels','Kanäle & Upload'],['analytics','Auswertung'],['system','System']];
const bytes=n=>Number.isFinite(n)?(n/1024**3).toLocaleString('de-DE',{maximumFractionDigits:1})+' GB':'—';
const date=v=>v?new Date(v).toLocaleString('de-DE',{day:'2-digit',month:'2-digit',hour:'2-digit',minute:'2-digit'}):'noch nicht abgefragt';
let toastTimer;
function toast(text){$('#toast').textContent=text;$('#toast').classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('visible'),6500)}
async function api(path,options={}){const method=options.method||'GET';const headers={'Content-Type':'application/json'};if(method!=='GET')headers['X-Cay-Token']=state.data?.csrf||'';const r=await fetch(path,{...options,headers:{...headers,...options.headers}});let data;try{data=await r.json()}catch{throw Error('Der lokale Server hat keine gültige Antwort geliefert.')}if(!r.ok)throw Error(typeof data.detail==='string'?data.detail:'Eingaben oder Verbindung prüfen.');return data}
function currentProject(){return state.data.projects.find(p=>p.id===state.project)||state.data.projects[0]}
function shell(){const root=state.data.windows_root;$('#app').innerHTML=`<aside><div class="brand-wrap"><div class="brand">Cay<span> Studio.</span></div><small>DEIN LOKALER FILMARBEITSPLATZ</small></div><nav aria-label="Hauptnavigation">${pages.map(([id,title],i)=>`<button data-page="${id}" class="${state.page===id?'active':''}"><span class="nav-no">0${i+1}</span>${e(title)}</button>`).join('')}</nav><div class="side-bottom"><div class="eyebrow">Lokales System</div><div id="side-status"></div><div class="spacer"></div><span class="path">${e(root)}</span><p>Studio ${e(state.data.version)}</p></div></aside><div class="shell"><header class="topbar"><div class="breadcrumb">Arbeitsplatz <span aria-hidden="true"> / </span> <b id="crumb"></b></div><div class="top-right"><span class="local-pill">Lokal auf deinem PC</span><span class="avatar" aria-label="Cay">CA</span></div></header><main id="view"></main></div>`;render();updateStatusUI()}
function head(kicker,title,description,actions=''){return `<div class="page-head"><div><div class="eyebrow">${e(kicker)}</div><h1>${e(title)}</h1><p class="muted">${e(description)}</p></div><div class="actions">${actions}</div></div>`}
function mediaCards(items){return `<div class="media-grid">${items.map(m=>`<article class="card film-card"><button class="poster" data-action="play" data-id="${m.id}" aria-label="${e(m.name)} ansehen"><img loading="lazy" src="/api/media/${m.id}/thumbnail" alt="Vorschaubild ${e(m.name)}"></button><div class="film-body"><span class="tag ${m.kind==='pilot'?'gold':''}">${m.kind==='film'?'FILMFASSUNG':'REGIEPILOT'}</span><h3>${e(m.name)}</h3><div class="film-meta">${e(m.project)} · ${(m.bytes/1024**2).toFixed(1)} MB</div></div></article>`).join('')}</div>`}
function projectCards(items){return `<div class="grid">${items.map((p,i)=>`<article class="card"><div class="project-number">PROJEKT ${String(i+1).padStart(2,'0')}</div><h3>${e(p.title)}</h3><p class="description">${e(p.brief||'Deine nächste Geschichte beginnt mit einer Idee.')}</p><footer><small>${e(p.format.replace('_',' '))}</small><div class="actions"><button class="small ghost" data-action="edit-project" data-id="${p.id}">Briefing</button><button class="small" data-action="project-chat" data-id="${p.id}">Zum Chat →</button></div></footer></article>`).join('')}</div>`}
function overview(){const d=state.data,films=d.media.filter(m=>m.kind==='film'),pilots=d.media.filter(m=>m.kind==='pilot'),active=(d.chat_jobs||[]).filter(j=>['queued','running'].includes(j.status));return head('Willkommen zurück, Cay','Dein Studio. Deine Geschichten.','Hier kommen Ideen, vorhandene Filme und dein lokaler Regiechat zusammen.')+`<section class="hero">${d.media[0]?`<img class="hero-image" src="/api/media/${d.media[0].id}/thumbnail" alt="">`:''}<div class="hero-copy"><div class="eyebrow">Von der Idee zur nächsten Szene</div><h1>Was drehen<br>wir als Nächstes?</h1><p>Entwickle eine neue Folge mit deinen Figuren. Dein Regiechat kennt das gespeicherte Projektbriefing und hält die Unterhaltung fest.</p><div class="actions"><button class="primary" data-page="chat">Idee im Regiechat besprechen →</button><button class="ghost" data-page="media">Vorhandene Filme ansehen</button></div><div class="hero-note">Jede Idee · eigene Figuren · eigener Stil</div></div></section><div class="stat-grid"><div class="stat"><span>Filmfassungen</span><strong>${films.length}</strong><small>In deiner Ablage auf D:</small></div><div class="stat"><span>Regiepiloten</span><strong>${pilots.length}</strong><small>Zum Vergleichen und Ansehen</small></div><div class="stat"><span>Projekte</span><strong>${d.projects.length}</strong><small>Mit eigenem Briefing</small></div><div class="stat"><span>Aktive Chat-Aufträge</span><strong>${active.length}</strong><small>GPU wird vor dem Start geprüft</small></div></div><div class="section-head"><h2>Deine Projekte</h2><button class="small ghost" data-action="new-project">+ Neues Projekt</button></div>${projectCards(d.projects.slice(0,3))}<div class="section-head"><h2>Zuletzt in deiner Ablage</h2><button class="small ghost" data-page="media">Alle Dateien →</button></div>${d.media.length?mediaCards(d.media.slice(0,4)):'<div class="empty"><strong>Noch keine Filme gefunden</strong>Prüfe die Ablage oder aktualisiere den Medienbestand.</div>'}<p class="footer-hint">Dein Studio verbindet Planung, Figurenreferenzen, Bildvarianten und Auswahl. Tonvorschau und Animation sind die nächsten Bausteine.</p>`}
function chatView(){const p=currentProject();state.project=p.id;return head('Regiechat','Eine gute Szene beginnt mit einer Idee.','Lokale Antworten von '+state.data.model+' · Gespräche werden auf deinem PC gespeichert.')+`<div class="chat-layout"><section class="chat-panel"><div class="chat-toolbar"><select id="chat-project" aria-label="Projekt auswählen">${state.data.projects.map(x=>`<option value="${x.id}" ${x.id===p.id?'selected':''}>${e(x.title)}</option>`).join('')}</select><button class="small primary" data-page="production">Produktionsentwurf →</button></div><div class="chat-log" id="chat-log" aria-live="polite"><div class="muted">Gespräch wird geladen …</div></div><div class="chat-status" id="chat-status"></div><form class="chat-compose" id="chat-form"><textarea id="chat-input" aria-label="Nachricht an den Regiechat" maxlength="100000" placeholder="Zum Beispiel: Die nächste Mafia-Folge soll mit einer falschen Kofferübergabe beginnen …" required></textarea><div class="compose-footer"><small>Bis 100.000 Zeichen · Enter sendet · Shift + Enter für eine neue Zeile</small><button class="primary" id="send-chat">Nachricht senden →</button></div></form></section><aside class="context-card"><div class="eyebrow">Projektgedächtnis</div><h3>${e(p.title)}</h3><p>${e(p.brief||'Noch keine festen Vorgaben gespeichert.')}</p><button class="small full" data-action="edit-project" data-id="${p.id}">Briefing bearbeiten</button><hr><p>Im Reiter Produktion wird aus deiner Idee ein gespeicherter Szenenentwurf. Erst Text prüfen, danach Figuren und Bilder auswählen. Bildvarianten lassen sich nach der Textfreigabe direkt in Produktion starten. Die Videoanbindung folgt danach.</p></aside></div>`}
function projectsView(){return head('Serien & Geschichten','Deine Projekte','Jedes Projekt behält seine Vorgaben und sein eigenes Gespräch.',`<button class="primary" data-action="new-project">+ Neues Projekt</button>`)+projectCards(state.data.projects)}
function mediaView(){const filtered=state.data.media.filter(m=>state.filter==='all'||m.kind===state.filter);return head('Deine Ablage auf D:','Filme & Vorschauen','Vorhandene Fassungen ansehen, herunterladen oder für einen manuellen Upload bereitstellen.',`<button data-action="refresh-media">Bestand aktualisieren</button>`)+`<div class="chips">${[['all','Alle Dateien'],['film','Filmfassungen'],['pilot','Regiepiloten']].map(([id,t])=>`<button class="${state.filter===id?'selected':''}" data-action="filter" data-id="${id}">${t}</button>`).join('')}</div>`+(filtered.length?mediaCards(filtered):'<div class="empty"><strong>Hier ist noch Platz für deinen nächsten Film.</strong>Abgeschlossene Exporte erscheinen nach dem Aktualisieren.</div>')+`<div class="notice">„Filmfassung“ bedeutet abgeschlossener Export. Frühere Fassungen können die bekannten inhaltlichen Fehler enthalten. Vorschauen werden getrennt gekennzeichnet.</div><p class="path">${e(state.data.windows_root)}\\03_Fertige_Videos</p>`}
function queueView(){const c=state.data.status.comfy||{},jobs=state.data.chat_jobs||[];return imageQueueView()+head('Live aus den lokalen Diensten','Warteschlange','Echte Aufträge und gespeicherte Chat-Aufgaben. Externe Renderaufträge werden hier nur angezeigt.')+`<div class="two-cols"><section class="card"><h2>ComfyUI</h2><p class="muted">${c.online?`${c.running||0} laufend · ${c.pending||0} wartend`:'Dienst nicht erreichbar / Status noch unbekannt'}</p>${(c.jobs||[]).length?(c.jobs||[]).map(j=>`<div class="list-row"><div><strong>${e(j.title)}</strong><small>${e(j.id)}</small></div><span class="tag">${e(j.state)}</span></div>`).join(''):`<div class="empty"><strong>${c.online?'Keine Renderaufträge':'Status wird abgefragt'}</strong>${c.online?'Die ComfyUI-Warteschlange ist frei.':'Bei ausgeschaltetem Dienst das Studio über den Startknopf öffnen.'}</div>`}<p class="footer-hint">Neue Filmaufträge, Schrittfortschritt und belastbare Restzeiten folgen mit der Produktionsanbindung.</p></section><section class="card"><h2>Regiechat</h2>${jobs.length?jobs.slice(0,12).map(j=>`<div class="list-row"><div><strong>${e(state.data.projects.find(p=>p.id===j.project_id)?.title||'Projekt')}</strong><small>${e(j.phase)}</small><small>${date(j.created)}</small>${j.error?`<small class="status-badge bad">${e(j.error)}</small>`:''}</div>${['queued','running'].includes(j.status)?`<button class="small danger" data-action="stop-chat" data-id="${j.id}">Stoppen</button>`:`<span class="tag">${e(statusLabel(j.status))}</span>`}</div>`).join(''):'<div class="empty">Noch keine Chat-Aufträge.</div>'}</section></div><div class="notice">Ein Regiechat-Auftrag wartet, solange ComfyUI laufende oder wartende Aufträge meldet. Während einer KI-Antwort bitte keine zusätzlichen schweren GPU-Aufträge außerhalb des Studios starten.</div>`}
function channelsView(){const exports=state.data.exports||[];return head('Veröffentlichung vorbereiten','Dein Film. Dein Kanal.','Lege passende Fassungen bereit und lade sie vorerst selbst hoch.')+`<div class="grid">${['TikTok','Instagram','YouTube'].map((name,i)=>`<section class="card"><span class="eyebrow">KANAL 0${i+1}</span><h2 class="kanal-title">${name}</h2><span class="tag">MANUELLER UPLOAD</span><p class="muted">${exports.filter(x=>x.platform===name).length} bereitgestellte Dateien</p><p class="path">04_Veroeffentlichung\\${name}\\Bereit</p><button class="full" data-page="media">Film auswählen →</button></section>`).join('')}</div><div class="notice">Wähle einen Film, öffne seine Vorschau und klicke auf „Für Upload bereitstellen“. Das legt eine Kopie im gewählten Kanalordner an. Es wird nichts an eine Plattform gesendet.</div><h2>Bereitgestellte Dateien</h2>${exports.length?`<section class="card">${exports.map(x=>`<div class="list-row"><div><strong>${e(x.platform)}</strong><p class="path">${e(state.data.windows_root+'\\'+x.path.replaceAll('/','\\'))}</p><small>${date(x.created)}</small></div></div>`).join('')}</section>`:'<div class="empty"><strong>Noch keine Kanalversion bereitgestellt</strong>Deine vorhandenen Filmfassungen bleiben unter „Filme & Vorschauen“ erreichbar.</div>'}<p class="footer-hint">Offizielle Kontoverbindungen und Terminierung folgen nach Prüfung des Plattformzugangs. TikTok Direct Post ist für ein privates Eigenbauwerkzeug eingeschränkt.</p>`}
function analyticsView(){return head('Leistung & Reichweite','Messbare Ergebnisse.','Kanalstatistiken erscheinen nach Anschluss einer geeigneten offiziellen Schnittstelle.')+`<div class="stat-grid">${['Aufrufe im Monat','Wiedergabezeit','Interaktionen','Veröffentlichte Beiträge'].map(n=>`<div class="stat"><span>${n}</span><strong>—</strong><small>Kanal noch nicht verbunden</small></div>`).join('')}</div><div class="notice">Es werden keine Reichweitenwerte erfunden. Bereitgestellte lokale Dateien sind noch keine veröffentlichten Beiträge.</div><section class="card"><h2>Schon lokal erfasst</h2><div class="metric-line"><span>Projekte</span><strong>${state.data.projects.length}</strong></div><div class="metric-line"><span>Filmfassungen</span><strong>${state.data.media.filter(x=>x.kind==='film').length}</strong></div><div class="metric-line"><span>Regiepiloten</span><strong>${state.data.media.filter(x=>x.kind==='pilot').length}</strong></div><p class="footer-hint">Chat-Aufträge speichern Dauer und Tokenzahlen, wenn Ollama sie liefert. Produktionsdurchsatz und Monatsberichte folgen mit der Renderanbindung.</p></section>`}
function systemView(){const s=state.data.status,c=s.comfy||{},o=s.ollama||{},g=s.gpu||{};return head('Lokaler Arbeitsplatz','System & Ablage','Die Werte stammen aus deinen laufenden Diensten.',`<button data-action="diagnose">Diagnose anzeigen</button>`)+`<div class="service-grid"><section class="card"><h3>ComfyUI</h3><p class="status-badge ${c.online?'':'bad'}">${c.online?'Erreichbar':'Nicht erreichbar / wird geprüft'}</p><div class="metric-line"><span>Version</span><strong>${e(c.version||'—')}</strong></div><div class="metric-line"><span>Laufend / wartend</span><strong>${c.online?`${c.running} / ${c.pending}`:'—'}</strong></div></section><section class="card"><h3>Ollama · ${e(state.data.model)}</h3><p class="status-badge ${o.online?'':'bad'}">${o.online?'Erreichbar':'Nicht erreichbar / wird geprüft'}</p><div class="metric-line"><span>Version</span><strong>${e(o.version||'—')}</strong></div><p class="model-list">${(o.models||[]).map(e).join('<br>')||'Modelle werden abgefragt.'}</p></section><section class="card"><h3>${e(g.name||'Grafikkarte')}</h3><div class="metric-line"><span>VRAM genutzt</span><strong>${g.used_mib!==undefined?`${(g.used_mib/1024).toFixed(1)} / ${(g.total_mib/1024).toFixed(1)} GB`:'—'}</strong></div><div class="metric-line"><span>Auslastung</span><strong>${g.utilization!==undefined?g.utilization+' %':'—'}</strong></div></section><section class="card"><h3>Ablage auf D:</h3><p class="path">${e(state.data.windows_root)}</p><div class="metric-line"><span>Freier Speicher</span><strong>${bytes(s.disk?.free)}</strong></div><p class="muted">Aktive Datenbank und Rechenumgebungen bleiben in WSL.</p></section></div><p class="footer-hint">Letzte Abfrage: ${date(s.updated_at)} · Studio ${e(state.data.version)}</p><div class="notice">Start per „Cay Studio starten“ auf D: oder über die Desktop-Verknüpfung. Das Schließen des Browserfensters beendet laufende Dienste und Chat-Aufträge nicht.</div>`}
function render(){if(!pages.some(p=>p[0]===state.page))state.page='overview';$('#crumb').textContent=pages.find(p=>p[0]===state.page)[1];document.querySelectorAll('nav button').forEach(b=>b.classList.toggle('active',b.dataset.page===state.page));const views={overview,chat:chatView,projects:projectsView,production:productionView,media:mediaView,queue:queueView,channels:channelsView,analytics:analyticsView,system:systemView};$('#view').innerHTML=views[state.page]();if(state.page==='chat'){state.chatSignature='';loadChat()}if(state.page==='production')loadProduction();window.scrollTo({top:0,behavior:'instant'})}
function updateStatusUI(){const s=state.data.status||{};const el=$('#side-status');if(el)el.innerHTML=[['ComfyUI',s.comfy?.online],['Ollama',s.ollama?.online]].map(([n,on])=>`<div class="side-line"><span>${n}</span><span><i class="dot ${on?'on':'off'}"></i>${on?'bereit':'prüfen'}</span></div>`).join('')}
function changePage(page){state.page=page;localStorage.setItem('cay.page',page);render()}
function statusLabel(s){return {done:'Fertig',failed:'Fehler',cancelled:'Gestoppt',interrupted:'Unterbrochen',queued:'Wartet',running:'Läuft',submitting:'Übergabe',submitted:'Wartet / rendert',uncertain:'Status unklar'}[s]||s}
async function loadChat(){const pid=state.project;try{const chat=await api('/api/projects/'+pid+'/chat');if(state.page!=='chat'||pid!==state.project)return;state.chat=chat;const sig=JSON.stringify(chat);if(sig===state.chatSignature)return;state.chatSignature=sig;const box=$('#chat-log');const nearBottom=box.scrollHeight-box.scrollTop-box.clientHeight<120;const active=chat.jobs.find(j=>['queued','running'].includes(j.status));const latest=chat.jobs[0];let markup=chat.messages.map(m=>`<div class="message ${m.role==='user'?'user':'assistant'}"><div class="name">${m.role==='user'?'CAY':'REGIEASSISTENT'}</div><div class="text">${m.role==='assistant'?markdown(m.content):e(m.content)}</div></div>`).join('');if(active?.content)markup+=`<div class="message"><div class="name">REGIEASSISTENT · SCHREIBT</div><div class="text">${markdown(active.content)}</div></div>`;if(!markup)markup='<div class="empty"><strong>Erzähl mir deine nächste Idee.</strong>Worum soll es gehen, wer spielt mit und welche Wirkung soll die Geschichte haben?</div>';if(latest&&['failed','interrupted','cancelled'].includes(latest.status))markup+=`<div class="notice warn">${e(latest.phase)}${latest.error?': '+e(latest.error):''}${latest.kind==='chat'?`<button class="small" data-action="resume-chat" data-id="${latest.id}">Fortsetzen</button>`:''}${latest.content?'<details><summary>Unvollständige Antwort anzeigen</summary><div class="message text">'+e(latest.content)+'</div></details>':''}</div>`;box.innerHTML=markup;if(nearBottom||!chat.messages.length)box.scrollTop=box.scrollHeight;$('#chat-status').innerHTML=active?`<span>${e(active.phase)} · ${Math.max(0,Math.round((Date.now()-Date.parse(active.created))/1000))} s seit Anfrage</span><button class="small danger" data-action="stop-chat" data-id="${active.id}">Stoppen</button>`:`<span>Gespräch gespeichert${latest?.status==='done'?' · '+jobTiming(latest):''}</span>`;if(latest?.content)$('#chat-status').insertAdjacentHTML('beforeend',`<a href="/api/chat/${latest.id}/download" download>Drehbuch speichern ↓</a>`);$('#send-chat').disabled=Boolean(active)}catch(err){toast(err.message)}}
function openDialog(content){const dialog=$('#dialog');dialog.innerHTML=content;if(!dialog.open)dialog.showModal();dialog.scrollTop=0}
function closeDialog(){const v=$('#dialog video');if(v)v.pause();$('#dialog').close();$('#dialog').innerHTML=''}
function editProject(id){const p=state.data.projects.find(x=>x.id===id);openDialog(`<div class="dialog-head"><div><div class="eyebrow">Projektgedächtnis</div><h2>${p?'Briefing bearbeiten':'Neues Projekt'}</h2></div><button class="small ghost" data-action="close">Schließen</button></div><form id="project-form" data-id="${p?.id||''}"><label for="project-title">Projekttitel</label><input id="project-title" name="title" value="${e(p?.title||'')}" minlength="2" maxlength="100" required><label for="project-format">Format</label><input id="project-format" name="format" class="full" list="format-examples" maxlength="80" value="${e(p?.format||'')}" placeholder="Zum Beispiel: Science-Fiction, Cartoon, Produktfilm …" ${p?'disabled':''} required><datalist id="format-examples"><option value="Mafia"><option value="Fruechte"><option value="Harry_Butter"></datalist><label for="project-brief">Feste Vorgaben und aktuelle Idee</label><textarea id="project-brief" name="brief" rows="9" maxlength="100000" placeholder="Figuren, Stimmung, Geschichte und offene Entscheidungen …">${e(p?.brief||'')}</textarea><p class="muted">Diese Notizen bekommt die KI bei jeder neuen Antwort. Sie werden zusätzlich versioniert im Projektordner auf D: abgelegt.</p><button class="primary" type="submit">Briefing speichern</button></form>`)}
function play(id){const m=state.data.media.find(x=>x.id===id);if(!m)return;openDialog(`<div class="dialog-head"><div><div class="eyebrow">${m.kind==='film'?'Filmfassung':'Regiepilot'}</div><h2>${e(m.name)}</h2></div><button class="small ghost" data-action="close">Schließen</button></div><video class="dialog-video" controls playsinline preload="metadata" src="/api/media/${m.id}/content"></video><p class="path">${e(m.windows_path)}</p><div class="dialog-footer"><a href="/api/media/${m.id}/content?download=true">MP4 herunterladen</a><select id="upload-platform" aria-label="Zielkanal"><option>TikTok</option><option>Instagram</option><option>YouTube</option></select><button data-action="prepare-upload" data-id="${m.id}">Für Upload bereitstellen</button></div><p class="footer-hint">Bereitstellen kopiert die Datei in den Kanalordner auf D:. Du entscheidest danach selbst über den Upload.</p>`)}
document.addEventListener('click',async ev=>{const b=ev.target.closest('[data-page],[data-action]');if(!b)return;if(b.dataset.page){changePage(b.dataset.page);return}const action=b.dataset.action,id=b.dataset.id;try{if(action==='play')play(id);if(action==='close')closeDialog();if(action==='new-project')editProject();if(action==='edit-project')editProject(id);if(action==='project-chat'){state.project=id;localStorage.setItem('cay.project',id);changePage('chat')}if(action==='filter'){state.filter=id;render()}if(action==='refresh-media'){b.disabled=true;const r=await api('/api/media/refresh',{method:'POST'});state.data.media=r.media;render();toast('Medienbestand aktualisiert.')}if(action==='resume-chat'){await api('/api/chat/'+id+'/resume',{method:'POST'});state.chatSignature='';await loadChat()}if(action==='stop-chat'){await api('/api/chat/'+id+'/stop',{method:'POST'});toast('Stopp angefordert.');await poll()}if(action==='prepare-upload'){b.disabled=true;const r=await api('/api/media/'+id+'/prepare-upload',{method:'POST',body:JSON.stringify({platform:$('#upload-platform').value})});const fresh=await api('/api/bootstrap');state.data.exports=fresh.exports;toast('Bereitgestellt: '+r.windows_path);b.disabled=false}if(action==='diagnose'){const d=await api('/api/system/diagnose');openDialog(`<div class="dialog-head"><h2>Systemdiagnose</h2><button data-action="close">Schließen</button></div><p>Ohne Gesprächsinhalte und Zugangsdaten.</p><pre>${e(JSON.stringify(d,null,2))}</pre>`)}}catch(err){b.disabled=false;toast(err.message)}});
document.addEventListener('change',ev=>{if(ev.target.id==='chat-project'){state.project=ev.target.value;localStorage.setItem('cay.project',state.project);render()}});
document.addEventListener('submit',async ev=>{if(!['chat-form','project-form'].includes(ev.target.id))return;ev.preventDefault();const form=ev.target,submit=form.querySelector('[type="submit"]')||$('#send-chat');submit.disabled=true;try{if(form.id==='chat-form'){const input=$('#chat-input');await api('/api/chat',{method:'POST',body:JSON.stringify({project_id:state.project,text:input.value})});input.value='';state.chatSignature='';await loadChat()}else{const p=state.data.projects.find(x=>x.id===form.dataset.id);const body={title:$('#project-title').value,format:p?.format||$('#project-format').value,brief:$('#project-brief').value};const result=await api(p?'/api/projects/'+p.id:'/api/projects',{method:p?'PUT':'POST',body:JSON.stringify(body)});if(p)state.data.projects=state.data.projects.map(x=>x.id===p.id?result:x);else state.data.projects.push(result);state.project=result.id;localStorage.setItem('cay.project',result.id);closeDialog();render();toast('Projektbriefing gespeichert.')}}catch(err){toast(err.message);submit.disabled=false}});
document.addEventListener('keydown',ev=>{if(ev.target.id==='chat-input'&&ev.key==='Enter'&&!ev.shiftKey&&!ev.isComposing){ev.preventDefault();if(!$('#send-chat').disabled)$('#chat-form').requestSubmit()}});
$('#dialog').addEventListener('cancel',ev=>{ev.preventDefault();closeDialog()});
async function poll(){if(!state.data||state.polling)return;state.polling=true;try{const r=await api('/api/status');state.data.status=r.system;state.data.chat_jobs=r.chat_jobs;state.data.image_jobs=r.image_jobs||[];updateStatusUI();if(['queue','system'].includes(state.page)&&!$('#dialog').open){const top=window.scrollY;render();window.scrollTo(0,top)}if(state.page==='chat')await loadChat();if(state.page==='production')await loadProduction()}catch(err){const el=$('#side-status');if(el)el.textContent='Studio-Verbindung unterbrochen.'}finally{state.polling=false}}
async function boot(){try{state.data=await api('/api/bootstrap');if(!state.data.projects.some(p=>p.id===state.project))state.project=state.data.projects[0].id;shell();setInterval(poll,2500)}catch(err){$('#app').innerHTML=`<main><h1>Studio noch nicht erreichbar.</h1><p>${e(err.message)}</p><p>Öffne „Cay Studio starten“ und lade diese Seite danach neu.</p></main>`}}
// Small safe formatter: user/model HTML is always escaped before adding our own tags.
function markdown(value){
 const clean=String(value??'').replace(/\\([*_`])/g,'$1');
 return e(clean).replace(/\*\*([^*\n]+)\*\*/g,'<strong>$1</strong>').replace(/`([^`\n]+)`/g,'<code>$1</code>');
}
function jobTiming(job){
 let m={};try{m=JSON.parse(job.metrics||'{}')}catch{}
 const total=(Date.parse(job.updated)-Date.parse(job.created))/1000;
 const pieces=[Number.isFinite(total)?Math.round(total)+' s inkl. Wartezeit':'Dauer unbekannt'];
 if(m.load_duration>=0)pieces.push((m.load_duration/1e9).toFixed(1)+' s Modell laden');
 if(m.eval_count>0&&m.eval_duration>0)pieces.push((m.eval_count/(m.eval_duration/1e9)).toFixed(1)+' Token/s');
 return pieces.join(' · ');
}
state.production={pid:null,list:null,selected:null,draft:null,signature:''};
function productionView(){const p=currentProject();state.project=p.id;return head('Idee → Szenenentwurf','Deine nächste Produktion','Die lokale KI plant Handlung, Dialog, Kamera und Ton. Du prüfst den Entwurf vor den nächsten Schritten.',`<div class="actions"><button data-action="project-visuals">Projektbilder & Stil</button><button class="primary" data-action="new-draft">+ Entwurf erstellen</button></div>`)+`<div class="production-toolbar"><select id="production-project" aria-label="Produktionsprojekt">${state.data.projects.map(x=>`<option value="${x.id}" ${x.id===p.id?'selected':''}>${e(x.title)}</option>`).join('')}</select><span class="tag">TEXT & REGIE</span></div><div class="pipeline"><span class="current">1 · Szenenentwurf</span><span>2 · Bildauswahl</span><span>3 · Tonvorschau</span><span>4 · Animation</span><span>5 · Export</span></div><p class="muted">Nach der Textfreigabe kannst du hier Bildvarianten erzeugen und auswählen. Tonvorschau, Animation und Upload werden danach angeschlossen.</p><div id="production-content"><div class="empty">Entwürfe werden geladen …</div></div>`}
async function loadProduction(){
 const pid=state.project;if(state.page!=='production')return;
 try{
  const list=await api('/api/projects/'+pid+'/drafts');if(state.page!=='production'||state.project!==pid)return;
  if(state.production.pid!==pid)state.production={pid,list,selected:null,draft:null,signature:''};
  if(list.drafts.some(d=>d.id===state.production.pendingSelection)){state.production.selected=state.production.pendingSelection;state.production.pendingSelection=null;}
  const selected=list.drafts.some(d=>d.id===state.production.selected)?state.production.selected:list.drafts[0]?.id;
  const draft=selected?await api('/api/drafts/'+selected):null;
  if(state.page!=='production'||state.project!==pid)return;
  state.production.list=list;state.production.selected=selected;state.production.draft=draft;
  const [imageSetup,imageState]=await Promise.all([api('/api/images/setup?project_id='+encodeURIComponent(pid)),draft?api('/api/drafts/'+draft.id+'/images'):Promise.resolve(null)]);
  if(state.page!=='production'||state.project!==pid)return;
  state.production.imageSetup=imageSetup;state.production.imageState=imageState;
  const sig=JSON.stringify({list,draft,imageSetup,imageState});
  if(sig!==state.production.signature||!$('#production-content .production-loaded')){
   state.production.signature=sig;$('#production-content').innerHTML=productionContent(list,draft);
  }
 }catch(err){toast(err.message)}
}
function productionContent(list,draft){
 const active=list.jobs.find(j=>['queued','running'].includes(j.status)),latest=list.jobs[0];
 let status=active?`<div class="notice"><strong>${e(active.phase)}</strong><p>Du kannst andere Reiter öffnen. Der Auftrag bleibt gespeichert.</p><button class="small danger" data-action="stop-chat" data-id="${active.id}">Entwurf stoppen</button></div>`:'';
 if(latest&&['failed','interrupted','cancelled'].includes(latest.status))status+=`<div class="notice warn">${e(latest.phase)}. ${e(latest.error||'Ein neuer Versuch kann über „Entwurf erstellen“ gestartet werden.')}</div>`;
 const variants=list.drafts.length?`<div class="chips">${list.drafts.map((d,i)=>`<button data-action="select-draft" data-id="${d.id}" class="${d.id===draft?.id?'selected':''}">Entwurf ${list.drafts.length-i} · v${d.revision}${d.status==='text_approved'?' ✓':''}</button>`).join('')}</div>`:'';
 if(!draft)return `<div class="production-loaded">${status}<div class="empty"><strong>Aus deiner Idee wird ein Szenenplan.</strong><p>Stimmung, Figuren und gewünschtes Ende einmal festlegen. Die KI übernimmt Dialog, Bildhandlung, Anschlüsse und Tonkonzept.</p><button data-action="new-draft" class="primary">Ersten Entwurf erstellen</button></div><div class="notice">${e(list.profile.name)} · ${e(list.profile.explanation)}</div></div>`;
 const doc=draft.document,story=doc.storyboard,profile=doc.technical_profile,seconds=story.scenes.reduce((sum,s)=>sum+s.seconds,0),job=list.jobs.find(j=>j.id===draft.id);
 let cursor=0;
 return `<div class="production-loaded">${status}${variants}${picturePanel(draft)}<section class="card draft-summary"><div class="section-head"><div><span class="eyebrow">${draft.status==='text_approved'?'TEXTFASSUNG FREIGEGEBEN':'ZUR PRÜFUNG'} · VERSION ${draft.revision}</span><h2>${e(story.title)}</h2></div><div class="actions"><button data-action="edit-draft">Entwurf bearbeiten</button><button class="primary" data-action="approve-draft" ${draft.status==='text_approved'||doc.checks.length?'disabled':''}>${draft.status==='text_approved'?'Text freigegeben ✓':'Textfassung freigeben'}</button></div></div><p>${e(story.logline)}</p><div class="chips"><span class="tag">${seconds} / ${doc.request.duration_seconds} Sekunden</span><span class="tag">${story.scenes.length} Szenen</span><span class="tag">${profile.timeline_fps} FPS Schnitt</span><span class="tag">Deutsche Untertitel</span></div><p class="path">${e(draft.windows_path)}</p>${job?.status==='done'?`<p class="muted">KI-Lauf: ${e(jobTiming(job))}</p>`:''}</section>${doc.checks.length?`<div class="notice warn"><strong>Vor der Textfreigabe prüfen</strong><ul>${doc.checks.map(x=>`<li>${e(x)}</li>`).join('')}</ul>${seconds!==doc.request.duration_seconds?`<button class="primary" data-action="fit-duration">Auf ${doc.request.duration_seconds} Sekunden planen</button><p class="footer-hint">Passt nur die geplanten Szenenzeiten an und speichert eine neue Fassung. Kein neuer KI-Lauf.</p>`:''}</div>`:''}${doc.timing_adjustment?`<div class="notice"><strong>Dauerplanung: ${doc.timing_adjustment.before_seconds} → ${doc.timing_adjustment.after_seconds} Sekunden</strong><p>${e(doc.timing_adjustment.note)}</p><details><summary>Geänderte Szenenzeiten</summary><ul>${doc.timing_adjustment.changes.map(x=>`<li>${e(x.scene)}: ${x.before} → ${x.after} Sekunden</li>`).join('')}</ul></details></div>`:''}${doc.timing_adjustment_error?`<div class="notice warn">${e(doc.timing_adjustment_error)}</div>`:''}${story.questions.length?`<section class="card"><h3>Offene kreative Fragen</h3><ol>${story.questions.map(q=>`<li>${e(q)}</li>`).join('')}</ol></section>`:''}<div class="storyboard">${story.scenes.map((s,i)=>{const start=cursor;cursor+=s.seconds;return `<article class="card scene-card"><div class="scene-header"><span class="eyebrow">S${String(i+1).padStart(2,'0')} · ${start}–${cursor} s</span><span class="tag">${e(s.cast.join(' · ')||'Detail / Umgebung')}</span></div><h3>${e(s.title)}</h3><p class="muted">${e(s.location)}</p><p>${e(s.action)}</p><dl><dt>Kamera</dt><dd>${e(s.camera)}</dd><dt>Anschluss</dt><dd>${e(s.continuity)}</dd></dl>${s.dialogue.map(d=>`<blockquote><strong>${e(d.speaker)}</strong><span class="muted"> · ${e(d.emotion)}</span><p>${e(d.text)}</p>${d.subtitle_de!==d.text?`<small>Untertitel: ${e(d.subtitle_de)}</small>`:''}</blockquote>`).join('')}<div class="scene-sound"><strong>Ton & sichtbarer Auslöser</strong><p>${e(s.sound)}</p></div></article>`}).join('')}</div><section class="card"><h3>Musik & Mischung</h3><p>${e(story.music)}</p><p class="muted">Musikdatei, Nutzungsrechte, Stimmen und Synchronität werden vor der Tonvorschau geprüft. Diese Hinweise sind noch keine erzeugten Audiospuren.</p></section><div class="notice"><strong>${e(profile.name)}</strong><p>${e(profile.explanation)}</p>Geplantes Auswahlbudget: ${profile.image_variants_per_scene} Bildvarianten je Szene. Vor Animation müssen die tatsächlichen Bilder von dir ausgewählt sein.</div></div>`;
}
function newDraft(){
 const p=currentProject(),key='cay.draft.form.'+p.id;let saved={};try{saved=JSON.parse(localStorage.getItem(key)||'{}')}catch{}
 const defaults={idea:'',duration_seconds:60,mood:p.format==='Mafia'?'Spannend, mit trockenem Humor':'Komisch und überraschend',ending:'Eine klare überraschende Wendung',cast:(state.production.imageSetup?.figures||[]).map(f=>f.role).join(', ')};const v={...defaults,...saved};
 state.production.requestKey=crypto.randomUUID().replaceAll('-','');
 openDialog(`<div class="dialog-head"><div><div class="eyebrow">${e(p.title)}</div><h2>Was soll passieren?</h2></div><button data-action="close">Schließen</button></div><form id="production-form"><label for="draft-idea">Deine grobe Idee</label><textarea id="draft-idea" name="idea" rows="4" minlength="12" maxlength="4000" required placeholder="Wer will was erreichen, und was geht dabei schief?">${e(v.idea)}</textarea><label for="draft-cast">Welche Figuren spielen mit?</label><input id="draft-cast" name="cast" minlength="2" maxlength="400" required value="${e(v.cast)}"><div class="two-cols"><div><label for="draft-mood">Welche Stimmung?</label><input id="draft-mood" name="mood" minlength="3" maxlength="150" required value="${e(v.mood)}"></div><div><label for="draft-duration">Länge</label><select id="draft-duration" name="duration_seconds">${[30,45,60].map(n=>`<option ${n===Number(v.duration_seconds)?'selected':''} value="${n}">${n} Sekunden</option>`).join('')}</select></div></div><label for="draft-ending">Wie soll es enden?</label><input id="draft-ending" name="ending" minlength="3" maxlength="400" required value="${e(v.ending)}"><div class="notice">Das gespeicherte Projektbriefing und die jüngsten Chatnachrichten werden berücksichtigt. Es wird ein neuer Entwurf angelegt; frühere Fassungen bleiben erhalten.</div><button class="primary" type="submit">Szenenentwurf erzeugen</button></form>`);
}
function editDraft(){const d=state.production.draft,s=d.document.storyboard;state.production.editing=d;
 openDialog(`<div class="dialog-head"><h2>Textfassung bearbeiten</h2><button data-action="close">Schließen</button></div><form id="draft-edit-form"><label>Titel<input name="title" required minlength="2" maxlength="100" value="${e(s.title)}"></label><label>Geschichte in einem Satz<textarea name="logline" required maxlength="500">${e(s.logline)}</textarea></label><label>Musik und Mischung<textarea name="music" required maxlength="600">${e(s.music)}</textarea></label><label>Offene Fragen – eine pro Zeile; nach Klärung entfernen<textarea name="questions" maxlength="1500">${e(s.questions.join('\n'))}</textarea></label>${s.scenes.map((scene,i)=>`<fieldset class="edit-scene" data-index="${i}"><legend>S${String(i+1).padStart(2,'0')}</legend><label>Titel<input name="title" required maxlength="100" value="${e(scene.title)}"></label><label>Dauer in Sekunden<input name="seconds" type="number" min="2" max="12" required value="${scene.seconds}"></label><label>Figuren, durch Kommas getrennt<input name="cast" value="${e(scene.cast.join(', '))}" maxlength="320"></label>${[['location','Ort',200],['action','Sichtbare Handlung',800],['camera','Kamera',250],['continuity','Anschluss',400],['sound','Ton und sichtbarer Auslöser',450]].map(([key,title,len])=>`<label>${title}<textarea name="${key}" required maxlength="${len}">${e(scene[key])}</textarea></label>`).join('')}<h3>Dialog</h3>${[...scene.dialogue,...(scene.dialogue.length<3?[{speaker:'',text:'',subtitle_de:'',emotion:''}]:[])].map(line=>`<div class="edit-dialogue"><label>Sprecher<input name="speaker" maxlength="60" value="${e(line.speaker)}"></label><label>Gesprochener Text (leer = Zeile entfernen)<textarea name="text" maxlength="450">${e(line.text)}</textarea></label><label>Deutscher Untertitel<input name="subtitle_de" maxlength="450" value="${e(line.subtitle_de)}"></label><label>Emotion<input name="emotion" maxlength="150" value="${e(line.emotion)}"></label></div>`).join('')}</fieldset>`).join('')}<p class="muted">Änderungen werden als neue Version gespeichert. Eine frühere Textfreigabe gilt danach nicht mehr.</p><button type="submit" class="primary">Neue Fassung speichern</button></form>`);
}
document.addEventListener('change',ev=>{if(ev.target.id==='production-project'){state.project=ev.target.value;localStorage.setItem('cay.project',state.project);state.production.signature='';render()}});
document.addEventListener('click',async ev=>{const b=ev.target.closest('[data-action]');if(!b)return;try{
 if(b.dataset.action==='new-draft')newDraft();
 if(b.dataset.action==='select-draft'){state.production.selected=b.dataset.id;state.production.signature='';await loadProduction()}
 if(b.dataset.action==='edit-draft')editDraft();
 if(b.dataset.action==='fit-duration'){
  b.disabled=true;const d=state.production.draft;
  await api('/api/drafts/'+d.id+'/fit-duration',{method:'POST',body:JSON.stringify({revision:d.revision,sha256:d.sha256})});
  await loadProduction();toast('Szenenzeiten angepasst und als neue Fassung gespeichert. Bitte die Textfassung prüfen.');
 }
 if(b.dataset.action==='approve-draft'){
  b.disabled=true;const d=state.production.draft;
  await api('/api/drafts/'+d.id+'/approve',{method:'POST',body:JSON.stringify({revision:d.revision,sha256:d.sha256})});
  await loadProduction();toast('Textfassung freigegeben. Bildauswahl und Animation haben weiterhin eigene Freigaben.');
 }
}catch(err){b.disabled=false;toast(err.message)}});
document.addEventListener('submit',async ev=>{
 if(!['production-form','draft-edit-form'].includes(ev.target.id))return;ev.preventDefault();const form=ev.target,button=form.querySelector('button[type="submit"]');button.disabled=true;
 try{
  if(form.id==='production-form'){
   const v=Object.fromEntries(new FormData(form));v.duration_seconds=Number(v.duration_seconds);
   localStorage.setItem('cay.draft.form.'+state.project,JSON.stringify(v));
   const submitted=await api('/api/production/draft',{method:'POST',body:JSON.stringify({...v,project_id:state.project,request_key:state.production.requestKey})});
   state.production.pendingSelection=submitted.id;state.production.selected=null;closeDialog();await loadProduction();toast('Entwurf steht in der lokalen KI-Warteschlange.');
  }else{
   const d=state.production.editing,field=(root,key)=>root.querySelector(`[name="${key}"]`).value.trim();
   const storyboard={title:field(form,'title'),logline:field(form,'logline'),music:field(form,'music'),questions:field(form,'questions').split('\n').map(x=>x.trim()).filter(Boolean),scenes:[]};
   storyboard.scenes=[...form.querySelectorAll('.edit-scene')].map(root=>({title:field(root,'title'),seconds:Number(field(root,'seconds')),cast:field(root,'cast').split(',').map(x=>x.trim()).filter(Boolean),location:field(root,'location'),action:field(root,'action'),camera:field(root,'camera'),continuity:field(root,'continuity'),sound:field(root,'sound'),dialogue:[...root.querySelectorAll('.edit-dialogue')].filter(r=>field(r,'text')).map(r=>({speaker:field(r,'speaker'),text:field(r,'text'),subtitle_de:field(r,'subtitle_de')||field(r,'text'),emotion:field(r,'emotion')||'Natürlich'}))}));
   await api('/api/drafts/'+d.id,{method:'PUT',body:JSON.stringify({revision:d.revision,storyboard})});closeDialog();await loadProduction();toast('Neue Version gespeichert.');
  }
 }catch(err){button.disabled=false;toast(err.message)}
});

function picturePanel(draft){
 const setup=state.production.imageSetup||{},images=state.production.imageState||{jobs:[],selected:[]};
 if(draft.status!=='text_approved')return '<div class="notice">Nach der Textfreigabe können hier Bildvarianten erzeugt werden.</div>';
 const count=draft.document.storyboard.scenes.length,active=images.jobs.some(j=>['queued','submitting','submitted','uncertain'].includes(j.status));
 return `<section class="card image-production"><div class="section-head"><div><span class="eyebrow">NÄCHSTER SCHRITT · BILDAUSWAHL</span><h2>${images.approved?'Bildauswahl freigegeben ✓':'Deine Szenen sichtbar machen'}</h2></div><div class="actions"><button data-action="project-visuals">Projektbilder & Stil</button><button data-action="prepare-images">Figuren & Bildworkflow prüfen</button><button class="primary" data-action="image-order" ${!setup.ready||active?'disabled':''}>Bildvarianten erstellen</button></div></div><p>Pro Szene zunächst zwei Standbilder. Wähle jeweils ein Bild nach Gesicht, Kleidung, Requisiten und Anschluss. Erst nach der Bildauswahl folgt die Tonvorschau; Animation wird hier noch nicht gestartet.</p>${setup.error?`<div class="notice warn">${e(setup.error)}</div>`:''}<p class="muted">${e(setup.profile||'Vorhandener Flux-Bildworkflow')} · ${setup.ready?'Workflow geprüft':'Bitte zuerst Figuren und Workflow prüfen'}</p><div class="figure-strip">${(setup.figures||[]).map(f=>`<figure><button data-action="figure-preview" data-id="${e(f.role)}"><img src="/api/images/figures/${encodeURIComponent(f.role)}?project_id=${encodeURIComponent(state.project)}" alt="Freigegebene Referenz ${e(f.role)}" loading="lazy"></button><figcaption><strong>${e(f.role)}</strong><small>${e(f.selection)}</small></figcaption></figure>`).join('')}</div><div class="actions"><button data-action="${images.paused?'resume-images':'pause-images'}">${images.paused?'Bildwarteschlange fortsetzen':'Nach aktuellem Bild pausieren'}</button>${active?`<button class="danger" data-action="cancel-images">Wartende Bilder stoppen</button>`:''}<span class="tag">${images.selected.length} / ${count} Szenen ausgewählt</span></div>${images.paused?'<div class="notice">Bildwarteschlange pausiert. Ein bereits übergebener Auftrag wird noch fertiggestellt.</div>':''}<div class="image-scenes">${draft.document.storyboard.scenes.map((scene,index)=>`<section><div class="section-head"><h3>S${String(index+1).padStart(2,'0')} · ${e(scene.title)}</h3><button class="small" data-action="image-order" data-scene="${index}" ${!setup.ready||active?'disabled':''}>Zwei neue Varianten</button></div><div class="image-variants">${images.jobs.filter(j=>j.scene===index).map(j=>{const selected=images.selected.some(s=>s.job_id===j.id);return `<article class="image-variant ${selected?'chosen':''}">${j.status==='done'?`<button class="image-preview" data-action="image-preview" data-id="${j.id}"><img src="/api/images/${j.id}/content" alt="Szene ${index+1}, Variante ${j.variant}" loading="lazy"></button>`:`<div class="image-placeholder"><strong>V${String(j.variant).padStart(2,'0')}</strong><p>${e(j.phase)}</p>${j.error?`<small>${e(j.error)}</small>`:''}</div>`}<div class="image-caption"><span>Variante ${j.variant} · ${e(statusLabel(j.status))}</span>${j.status==='done'?`<button class="${selected?'primary':''}" data-action="select-image" data-id="${j.id}">${selected?'Ausgewählt ✓':'Dieses Bild wählen'}</button>`:''}${j.status==='uncertain'?`<button data-action="recover-image" data-id="${j.id}">Status erneut prüfen</button>`:''}</div></article>`}).join('')||'<div class="empty">Noch keine Bildvarianten für diese Szene.</div>'}</div></section>`).join('')}</div><div class="notice">Standbilder bilden jeweils einen Moment ab. Kameraschwenks und mehrere Handlungsschritte aus dem Text werden vor Animation noch in passende Einstellungen aufgeteilt.</div><button class="primary" data-action="approve-images" ${images.selected.length!==count||images.approved?'disabled':''}>${images.approved?'Bildauswahl gespeichert ✓':'Bildauswahl freigeben'}</button>${images.approved?'<p class="muted">Bilder und Zuordnung sind gespeichert. Die Tonvorschau wird im nächsten Ausbau angeschlossen.</p>':''}</section>`;
}
function imageOrderDialog(scene){
 const d=state.production.draft,setup=state.production.imageSetup,scope=Number.isInteger(scene)?scene:null;
 state.production.imageOrder={draft:d,setup,scene:scope,key:crypto.randomUUID().replaceAll('-','')};
 const count=scope===null?d.document.storyboard.scenes.length*2:2;
 openDialog(`<div class="dialog-head"><div><span class="eyebrow">BILDAUFTRAG · ${count} BILDER</span><h2>${scope===null?'Szenenvarianten erzeugen':'Szene '+(scope+1)+' erneut gestalten'}</h2></div><button data-action="close">Schließen</button></div><p>Dein vorhandenes Flux-Modell erzeugt ${count} Bilder mit neuen Seeds. Ergebnisse erscheinen hier und auf D:. Es startet keine Animation.</p><div class="figure-strip">${setup.figures.map(f=>`<figure><img src="/api/images/figures/${encodeURIComponent(f.role)}?project_id=${encodeURIComponent(state.project)}" alt="Referenz ${e(f.role)}"><figcaption>${e(f.role)} · ${e(f.selection)}</figcaption></figure>`).join('')}</div><form id="image-order-form"><label for="image-direction">Optionaler Änderungswunsch für die Bilder</label><textarea id="image-direction" maxlength="500" rows="3" placeholder="Gewünschte Änderungen an Perspektive, Handlung oder Licht …"></textarea><label class="check-label"><input id="image-refs-checked" type="checkbox" required>Projektstil und die angezeigten Referenzen passen. Für benannte Figuren habe ich Referenzen zugeordnet.</label><p class="muted">Die Aufträge starten nacheinander, sobald ComfyUI frei und das Sprachmodell entladen ist. Du kannst den Browser schließen; das Studio muss weiterlaufen.</p><button class="primary" type="submit">${count} Bilder in die Warteschlange stellen</button></form>`);
}
function imageQueueView(){const jobs=state.data.image_jobs||[];return `<section class="card"><h2>Studio-Bildaufträge</h2>${jobs.length?jobs.map(j=>`<div class="list-row"><div><strong>S${String(j.scene+1).padStart(2,'0')} · Variante ${j.variant}</strong><small>${e(j.phase)}</small>${j.error?`<small>${e(j.error)}</small>`:''}</div><span class="tag">${e(statusLabel(j.status))}</span></div>`).join(''):'<p class="muted">Noch keine Bildaufträge. Im Reiter Produktion einen freigegebenen Entwurf öffnen.</p>'}</section>`}
document.addEventListener('click',async ev=>{
 const b=ev.target.closest('[data-action]');if(!b)return;
 const action=b.dataset.action,id=b.dataset.id,d=state.production.draft;
 if(!['prepare-images','image-order','figure-preview','image-preview','select-image','approve-images','pause-images','resume-images','cancel-images','recover-image'].includes(action))return;
 try{
  if(action==='prepare-images'){b.disabled=true;b.textContent='Prüfe …';state.production.imageSetup=await api('/api/images/prepare?project_id='+encodeURIComponent(state.project),{method:'POST'});state.production.signature='';await loadProduction();toast('Projektfiguren und vorhandener Bildworkflow geprüft.');}
  if(action==='image-order')imageOrderDialog(b.dataset.scene===undefined?null:Number(b.dataset.scene));
  if(action==='figure-preview'||action==='image-preview')openDialog(`<div class="dialog-head"><h2>${action==='figure-preview'?e(id):'Bildvariante prüfen'}</h2><button data-action="close">Schließen</button></div><img class="large-image" src="${action==='figure-preview'?'/api/images/figures/'+encodeURIComponent(id)+'?project_id='+encodeURIComponent(state.project):'/api/images/'+id+'/content'}" alt="Große Bildansicht">${action==='image-preview'?`<a href="/api/images/${id}/content?download=true">PNG herunterladen</a>`:''}`);
  if(action==='select-image'){b.disabled=true;const job=state.production.imageState.jobs.find(j=>j.id===id);await api('/api/drafts/'+d.id+'/images/select',{method:'POST',body:JSON.stringify({job_id:id,sha256:job.sha256})});await loadProduction();}
  if(action==='approve-images'){b.disabled=true;await api('/api/drafts/'+d.id+'/images/approve',{method:'POST',body:JSON.stringify({draft_sha256:d.sha256,selection_sha256:state.production.imageState.selection_sha256})});await loadProduction();toast('Bildauswahl gespeichert. Es wurde keine Animation gestartet.');}
  if(action==='pause-images'||action==='resume-images'){await api('/api/images/'+(action==='pause-images'?'pause':'resume'),{method:'POST'});await loadProduction();}
  if(action==='cancel-images'){await api('/api/drafts/'+d.id+'/images/cancel-pending',{method:'POST'});await loadProduction();toast('Wartende Studio-Bilder gestoppt. Ein laufendes Bild bleibt erhalten.');}
  if(action==='recover-image'){await api('/api/images/'+id+'/recover',{method:'POST'});await loadProduction();toast('Vorhandener Auftrag wird gesucht. Keine neue Übergabe.');}
 }catch(err){b.disabled=false;if(action==='prepare-images')b.textContent='Figuren & Bildworkflow prüfen';toast(err.message)}
});
document.addEventListener('submit',async ev=>{
 if(ev.target.id!=='image-order-form')return;ev.preventDefault();const button=ev.target.querySelector('button[type="submit"]');button.disabled=true;
 try{
  const order=state.production.imageOrder;
  await api('/api/drafts/'+order.draft.id+'/images',{method:'POST',body:JSON.stringify({revision:order.draft.revision,sha256:order.draft.sha256,cast_sha256:order.setup.cast_sha256,request_key:order.key,scene:order.scene,note:$('#image-direction').value,references_checked:$('#image-refs-checked').checked})});
  closeDialog();await loadProduction();toast('Bildaufträge gespeichert. Ergebnisse erscheinen automatisch unter deinem Entwurf.');
 }catch(err){button.disabled=false;toast(err.message)}
});

async function projectVisuals(){
 const pid=state.project;
 const [setup,incoming]=await Promise.all([api('/api/images/setup?project_id='+encodeURIComponent(pid)),api('/api/images/incoming')]);
 state.visualProject=pid;
 openDialog(`<div class="dialog-head"><div><span class="eyebrow">NUR FÜR DIESES PROJEKT</span><h2>Projektbilder & Stil</h2></div><button data-action="close">Schließen</button></div><p>${e(currentProject().title)}: Figuren und Stil werden unabhängig von anderen Projekten gespeichert. Bereits angelegte Bildaufträge behalten ihre gesicherten Vorgaben.</p><form id="visual-style-form"><label for="visual-style">Bildstil</label><textarea id="visual-style" rows="4" minlength="5" maxlength="2000" required>${e(setup.style)}</textarea><button type="submit">Bildstil speichern</button></form><hr><h3>Figurenreferenzen</h3><div class="figure-strip">${setup.figures.map(f=>`<figure><img src="/api/images/figures/${encodeURIComponent(f.role)}?project_id=${encodeURIComponent(pid)}" alt="${e(f.role)}"><figcaption><strong>${e(f.role)}</strong><small>${e(f.traits)}</small><button class="small" data-action="remove-figure" data-id="${e(f.role)}">Zuordnung entfernen</button></figcaption></figure>`).join('')||'<p>Noch keine Figuren zugeordnet.</p>'}</div><p>Lege Referenzbilder als PNG in <strong>D:\\Cay_Studio\\00_Eingang\\Bilder</strong> ab. Öffne dieses Fenster danach erneut. Benutze dieselben Figurennamen wie im Szenenentwurf. Details und Landschaften ohne Figuren benötigen kein Referenzbild.</p><form id="figure-form"><label for="figure-role">Figurenname</label><input id="figure-role" maxlength="80" required placeholder="Zum Beispiel: Erdbeere Rosa"><label for="figure-source">PNG aus dem Eingangsordner</label><select id="figure-source" required><option value="">Bild auswählen …</option>${incoming.files.map(f=>`<option value="${f.id}">${e(f.name)}</option>`).join('')}</select><label for="figure-traits">Aussehen, Kleidung und feste Merkmale</label><textarea id="figure-traits" rows="3" maxlength="1500" placeholder="Gilt nur für diese Figur in diesem Projekt"></textarea><p class="muted">Ein vorhandener Figurenname ersetzt dessen Zuordnung für künftige Bildaufträge. Alte Referenzdateien und Aufträge bleiben erhalten.</p><button type="submit" class="primary" ${incoming.files.length?'':'disabled'}>Referenz zuordnen</button></form>`);
}
document.addEventListener('click',async ev=>{
 const b=ev.target.closest('[data-action]');if(!b)return;
 try{
  if(b.dataset.action==='project-visuals')await projectVisuals();
  if(b.dataset.action==='remove-figure'){
   b.disabled=true;await api('/api/projects/'+state.visualProject+'/figures/'+encodeURIComponent(b.dataset.id),{method:'DELETE'});await projectVisuals();await loadProduction();
  }
 }catch(err){b.disabled=false;toast(err.message)}
});
document.addEventListener('submit',async ev=>{
 const form=ev.target;if(!['visual-style-form','figure-form'].includes(form.id))return;
 ev.preventDefault();const button=form.querySelector('button[type="submit"]');button.disabled=true;
 try{
  const pid=state.visualProject;
  if(form.id==='visual-style-form')await api('/api/projects/'+pid+'/image-profile',{method:'PUT',body:JSON.stringify({style:$('#visual-style').value})});
  else await api('/api/projects/'+pid+'/figures',{method:'POST',body:JSON.stringify({role:$('#figure-role').value,source_id:$('#figure-source').value,traits:$('#figure-traits').value})});
  toast('Projektvorgaben gespeichert.');await projectVisuals();await loadProduction();
 }catch(err){button.disabled=false;toast(err.message)}
});

boot();
